#!/usr/bin/env python3
"""hwatch 0.3.19 - A modern alternative to the watch command"""
import sys, os, re, json, time, shlex, subprocess, threading, argparse, signal
import curses, curses.textpad, queue, select
from datetime import datetime
from dataclasses import dataclass
from typing import Optional, List, Tuple
from enum import Enum

VERSION = "0.3.19"

class DiffMode(Enum):
    NONE = "none"
    WATCH = "watch"
    LINE = "line"
    WORD = "word"

class OutputMode(Enum):
    OUTPUT = "output"
    STDOUT = "stdout"
    STDERR = "stderr"

@dataclass
class CommandResult:
    timestamp: str = ""
    command: str = ""
    status: bool = True
    output: str = ""
    stdout: str = ""
    stderr: str = ""

    def to_dict(self):
        return {"timestamp": self.timestamp, "command": self.command,
                "status": self.status, "output": self.output,
                "stdout": self.stdout, "stderr": self.stderr}

    def to_json(self):
        return json.dumps(self.to_dict(), ensure_ascii=False)

    @classmethod
    def from_dict(cls, d):
        return cls(timestamp=d.get("timestamp",""), command=d.get("command",""),
                   status=d.get("status",True), output=d.get("output",""),
                   stdout=d.get("stdout",""), stderr=d.get("stderr",""))

    def get_display(self, mode: OutputMode) -> str:
        if mode == OutputMode.STDOUT: return self.stdout
        elif mode == OutputMode.STDERR: return self.stderr
        return self.output

def get_timestamp():
    now = datetime.now()
    return now.strftime("%Y-%m-%d %H:%M:%S.") + f"{now.microsecond//1000:03d}"

def parse_interval(s):
    try:
        val = float(s)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid float literal")
    if val < 0.001:
        val = 0.001
    return val

def format_interval(v):
    return f"{v:.3f}".rjust(9)

def run_command(command_parts, exec_mode=False, shell_cmd="sh -c"):
    if exec_mode:
        try:
            proc = subprocess.Popen(command_parts, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception as e:
            err = str(e)+"\n"
            return "", err, 1, err
    else:
        shell_parts = shlex.split(shell_cmd)
        cmd_str = " ".join(command_parts)
        if "{COMMAND}" in shell_cmd:
            final = [p.replace("{COMMAND}", cmd_str) for p in shell_parts]
        else:
            final = shell_parts + [cmd_str]
        try:
            proc = subprocess.Popen(final, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception as e:
            err = str(e)+"\n"
            return "", err, 1, err

    stdout_data, stderr_data, output_data = [], [], []
    rlist = [proc.stdout, proc.stderr]
    while rlist:
        try:
            ready, _, _ = select.select(rlist, [], [], 0.05)
        except (ValueError, OSError):
            break
        if not ready:
            if proc.poll() is not None:
                # drain remaining
                for fd in rlist:
                    chunk = fd.read()
                    if chunk:
                        if fd is proc.stdout:
                            stdout_data.append(chunk); output_data.append(chunk)
                        else:
                            stderr_data.append(chunk); output_data.append(chunk)
                break
            continue
        for fd in ready:
            chunk = fd.read(4096)
            if not chunk:
                rlist.remove(fd)
            else:
                if fd is proc.stdout:
                    stdout_data.append(chunk)
                else:
                    stderr_data.append(chunk)
                output_data.append(chunk)
    proc.wait()
    stdout = b"".join(stdout_data).decode("utf-8", errors="replace")
    stderr = b"".join(stderr_data).decode("utf-8", errors="replace")
    output = b"".join(output_data).decode("utf-8", errors="replace")
    return stdout, stderr, proc.returncode, output

def lcs_diff(old_lines, new_lines):
    n, m = len(old_lines), len(new_lines)
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if old_lines[i] == new_lines[j]:
                dp[i][j] = dp[i+1][j+1]+1
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])
    result, i, j = [], 0, 0
    while i < n or j < m:
        if i < n and j < m and old_lines[i] == new_lines[j]:
            result.append(('equal', old_lines[i])); i+=1; j+=1
        elif i < n and (j >= m or dp[i+1][j] >= dp[i][j+1]):
            result.append(('delete', old_lines[i])); i+=1
        else:
            result.append(('insert', new_lines[j])); j+=1
    return result

def word_lcs_diff(old_words, new_words):
    n, m = len(old_words), len(new_words)
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if old_words[i] == new_words[j]:
                dp[i][j] = dp[i+1][j+1]+1
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])
    result, i, j = [], 0, 0
    while j < m:
        if i < n and old_words[i] == new_words[j]:
            result.append((new_words[j], False)); i+=1; j+=1
        elif i < n and (j >= m or dp[i+1][j] >= dp[i][j+1]):
            i+=1
        else:
            result.append((new_words[j], True)); j+=1
    return result

def compute_summary(old_text, new_text, char_level=False):
    def splitlines(t):
        if not t: return []
        lines = t.split('\n')
        if lines and lines[-1] == '': lines = lines[:-1]
        return lines
    old_lines = splitlines(old_text)
    new_lines = splitlines(new_text)
    diff = lcs_diff(old_lines, new_lines)
    added = sum(1 for op,_ in diff if op=='insert')
    deleted = sum(1 for op,_ in diff if op=='delete')
    if not char_level:
        return added, deleted, 0, 0
    char_added = sum(len(l) for op,l in diff if op=='insert')
    char_deleted = sum(len(l) for op,l in diff if op=='delete')
    return added, deleted, char_added, char_deleted

def strip_ansi(text):
    return re.sub(r'\x1b\[[0-9;]*[mKHJA-Za-z]', '', text)

def expand_tabs(text, tab_size=4):
    result, col = [], 0
    for ch in text:
        if ch == '\t':
            sp = tab_size - (col % tab_size)
            result.append(' ' * sp); col += sp
        elif ch == '\n':
            result.append('\n'); col = 0
        else:
            result.append(ch); col += 1
    return ''.join(result)

# ─── ANSI color rendering helpers ───

def ansi_color_pair(fg, bg, bold=False, reverse=False):
    """Return curses color attributes approximation."""
    attr = 0
    if bold: attr |= curses.A_BOLD
    if reverse: attr |= curses.A_REVERSE
    return attr

# Color pair management
_color_pairs = {}
_next_pair = 1

def get_color_pair(fg, bg):
    global _next_pair
    key = (fg, bg)
    if key not in _color_pairs:
        if _next_pair < curses.COLOR_PAIRS:
            try:
                curses.init_pair(_next_pair, fg, bg)
                _color_pairs[key] = _next_pair
                _next_pair += 1
            except:
                return 0
        else:
            return 0
    return _color_pairs[key]

def parse_ansi_to_spans(text):
    """Parse ANSI text into list of (text_chunk, fg, bg, bold, reverse) tuples."""
    spans = []
    fg, bg, bold, reverse = -1, -1, False, False
    i = 0
    current = []

    def flush():
        if current:
            spans.append((''.join(current), fg, bg, bold, reverse))
            current.clear()

    while i < len(text):
        if text[i] == '\x1b' and i+1 < len(text) and text[i+1] == '[':
            j = i+2
            while j < len(text) and text[j] not in 'ABCDEFGHJKSTfmsu':
                j += 1
            if j < len(text) and text[j] == 'm':
                flush()
                seq = text[i+2:j]
                parts = seq.split(';') if seq else ['0']
                k = 0
                while k < len(parts):
                    try: n = int(parts[k]) if parts[k] else 0
                    except: n = 0
                    if n == 0: fg, bg, bold, reverse = -1, -1, False, False
                    elif n == 1: bold = True
                    elif n == 7: reverse = True
                    elif n == 22: bold = False
                    elif n == 27: reverse = False
                    elif 30 <= n <= 37: fg = n-30
                    elif n == 38:
                        if k+2 < len(parts) and parts[k+1] == '5':
                            try: fg = int(parts[k+2])+8 if int(parts[k+2]) > 7 else int(parts[k+2])
                            except: pass
                            k += 2
                        elif k+4 < len(parts) and parts[k+1] == '2':
                            # RGB - approximate to nearest curses color
                            try:
                                r,g,b = int(parts[k+2]),int(parts[k+3]),int(parts[k+4])
                                fg = rgb_to_curses(r, g, b)
                            except: pass
                            k += 4
                    elif n == 39: fg = -1
                    elif 40 <= n <= 47: bg = n-40
                    elif n == 48:
                        if k+2 < len(parts) and parts[k+1] == '5':
                            try: bg = int(parts[k+2])+8 if int(parts[k+2]) > 7 else int(parts[k+2])
                            except: pass
                            k += 2
                        elif k+4 < len(parts) and parts[k+1] == '2':
                            try:
                                r,g,b = int(parts[k+2]),int(parts[k+3]),int(parts[k+4])
                                bg = rgb_to_curses(r, g, b)
                            except: pass
                            k += 4
                    elif n == 49: bg = -1
                    elif 90 <= n <= 97: fg = n-90+8
                    elif 100 <= n <= 107: bg = n-100+8
                    k += 1
                i = j+1
                continue
            i = j+1
            continue
        current.append(text[i])
        i += 1
    flush()
    return spans

def rgb_to_curses(r, g, b):
    """Approximate RGB color to curses color index."""
    # Map to 16 basic colors
    if r < 64 and g < 64 and b < 64: return 0  # black
    if r > 192 and g < 64 and b < 64: return 1  # red
    if r < 64 and g > 128 and b < 64: return 2  # green
    if r > 128 and g > 128 and b < 64: return 3  # yellow
    if r < 64 and g < 64 and b > 128: return 4  # blue
    if r > 128 and g < 64 and b > 128: return 5  # magenta
    if r < 64 and g > 128 and b > 128: return 6  # cyan
    if r > 128 and g > 128 and b > 128: return 7  # white
    return 7  # default to white

