# ─── TUI main loop ───

def run_tui_mode(stdscr, args, command_parts, logfile_path, diff_mode, output_mode, initial_results=None):
    """Main TUI loop."""
    # Setup curses
    curses.start_color()
    curses.use_default_colors()
    curses.noecho()
    curses.cbreak()
    try:
        curses.curs_set(0)
    except: pass
    stdscr.keypad(True)
    stdscr.nodelay(True)

    state = AppState(args, command_parts, diff_mode, output_mode, initial_results)

    # Setup logfile
    logfile = None
    if logfile_path:
        logfile = LogFile(logfile_path)
        logfile.open()
        logfile.write(CommandResult())

    command_str = " ".join(command_parts)
    prev_output = state.history[-1].output if state.history else ""

    # Thread for running commands
    cmd_queue = queue.Queue()
    stop_event = threading.Event()

    def command_thread():
        while not stop_event.is_set():
            if state.paused:
                time.sleep(0.1)
                continue

            start = time.time()
            ts = get_timestamp()

            try:
                stdout, stderr, rc, output = run_command(
                    command_parts, exec_mode=args.exec_mode, shell_cmd=args.shell)
            except Exception as e:
                stdout, stderr, rc, output = "", str(e), 1, str(e)

            result = CommandResult(
                timestamp=ts, command=command_str,
                status=(rc==0), output=output,
                stdout=stdout, stderr=stderr)

            cmd_queue.put(result)

            elapsed = time.time() - start
            if args.precise:
                sleep_t = max(0, state.interval - elapsed)
            else:
                sleep_t = state.interval

            # Sleep in small chunks to allow stopping
            slept = 0
            while slept < sleep_t and not stop_event.is_set():
                time.sleep(min(0.05, sleep_t - slept))
                slept += 0.05

    cmd_thread = threading.Thread(target=command_thread, daemon=True)
    cmd_thread.start()

    last_ts = get_timestamp()

    try:
        while True:
            height, width = stdscr.getmaxyx()
            state.terminal_size = (width, height)

            # Process command results
            while True:
                try:
                    result = cmd_queue.get_nowait()
                    changed = state.add_result(result)
                    last_ts = result.timestamp

                    if changed:
                        if logfile:
                            logfile.write(result)

                        if args.aftercommand:
                            prev_r = state.history[-2] if len(state.history) >= 2 else CommandResult()
                            hwatch_data = json.dumps({
                                "before_result": prev_r.to_dict(),
                                "after_result": result.to_dict()
                            })
                            env = os.environ.copy()
                            env['HWATCH_DATA'] = hwatch_data
                            try:
                                subprocess.Popen(
                                    shlex.split(args.shell) + [args.aftercommand],
                                    env=env)
                            except: pass

                        if state.beep:
                            curses.beep()

                        state.needs_redraw = True
                except queue.Empty:
                    break

            # Handle input
            try:
                key = stdscr.getch()
            except:
                key = -1

            if key != -1:
                action = handle_key(state, key, stdscr)
                if action == 'quit':
                    break
                state.needs_redraw = True

            # Redraw
            if state.needs_redraw:
                draw_screen(stdscr, state, height, width, last_ts)
                state.needs_redraw = False

            time.sleep(0.02)  # ~50fps max

    finally:
        stop_event.set()
        if logfile:
            logfile.close()

def draw_screen(stdscr, state, height, width, last_ts):
    """Full screen redraw."""
    try:
        stdscr.erase()

        if state.show_title:
            # Row 0: header
            render_header(stdscr, state, width, last_ts)
            # Row 1: status
            render_status(stdscr, state, width, row=1)
            content_start = 2

            if state.show_border:
                render_border(stdscr, state, width, row=2)
                content_start = 3
        else:
            content_start = 0

        content_height = height - content_start

        # Watch pane
        watch_width = width - (HISTORY_WIDTH + 1) if state.show_history else width
        render_watch_pane(stdscr, state, content_start, content_height, width)

        # Vertical separator and history pane
        if state.show_history:
            render_vertical_separator(stdscr, state, content_start, content_height, width)
            render_history_pane(stdscr, state, content_start, content_height, width)

        # Help overlay
        if state.show_help:
            render_help_overlay(stdscr, state, width, height)

        stdscr.refresh()
    except Exception as e:
