def main():
    parser, env_args = build_argparser()

    # Parse env args first, then command line
    all_args = env_args + sys.argv[1:]

    try:
        args = parser.parse_args(all_args)
    except SystemExit as e:
        sys.exit(e.code)

    command_parts, logfile_path, diff_mode, output_mode = validate_args(args, parser)

    # Handle logfile
    initial_results = []
    if logfile_path:
        if os.path.exists(logfile_path):
            # Check if file is empty
            if os.path.getsize(logfile_path) == 0:
                # Prompt user
                sys.stderr.write(f'file "{logfile_path}" is exists and empty.\n')
                sys.stderr.write('Log to the same file? (Y/n) ')
                sys.stderr.flush()
                try:
                    ans = sys.stdin.readline().strip()
                except:
                    ans = 'Y'
                if ans.lower() == 'n':
                    sys.exit(0)
            else:
                # Read existing content
                existing = LogFile.read(logfile_path)
                # Find entries with actual data (non-empty timestamps)
                for r in existing:
                    if r.timestamp and r.command:
                        initial_results.append(r)

                # If no command specified, use command from log
                if not command_parts and initial_results:
                    command_parts = shlex.split(initial_results[-1].command) if initial_results else []
                    args.command = command_parts
        else:
            # File doesn't exist - check directory
            dirpath = os.path.dirname(os.path.abspath(logfile_path))
            if not os.path.exists(dirpath):
                print(f'error: directory is not exists.', file=sys.stderr)
                sys.exit(2)

    # Must have command at this point
    if not command_parts:
        print("error: command not specified and logfile is empty.\n", file=sys.stderr)
        print(f"Usage: hwatch [OPTIONS] [command]...\n", file=sys.stderr)
        print(f"For more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    # Run mode
    if args.batch:
        run_batch_mode(args, command_parts, logfile_path, diff_mode, output_mode)
    else:
        try:
            curses.wrapper(run_tui_mode, args, command_parts, logfile_path,
                          diff_mode, output_mode, initial_results if initial_results else None)
        except KeyboardInterrupt:
            pass

if __name__ == '__main__':
    main()

